  'Temporary OTP block time refers to a security measure implemented by systems to restrict access to OTP service for a specified period of time for wrong OTP submission.' => 'يشير وقت حظر رمز التحقق المؤقت إلى إجراء أمني لتقييد الوصول عند إدخال رمز تحقق خاطئ.',
  'Temporary login block time refers to a security measure implemented by systems to restrict access to for a specified period of time for wrong Password submission.' => 'يشير وقت حظر الدخول المؤقت إلى إجراء أمني لتقييد الوصول لفترة محددة عند إدخال كلمة مرور خاطئة.',
